def test_list_intelligence_findings_pager(transport_name: str = "grpc"):
    client = StorageControlClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_intelligence_findings), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            storage_control.ListIntelligenceFindingsResponse(
                intelligence_findings=[
                    storage_control.IntelligenceFinding(),
                    storage_control.IntelligenceFinding(),
                    storage_control.IntelligenceFinding(),
                ],
                next_page_token="abc",
            ),
            storage_control.ListIntelligenceFindingsResponse(
                intelligence_findings=[],
                next_page_token="def",
            ),
            storage_control.ListIntelligenceFindingsResponse(
                intelligence_findings=[
                    storage_control.IntelligenceFinding(),
                ],
                next_page_token="ghi",
            ),
            storage_control.ListIntelligenceFindingsResponse(
                intelligence_findings=[
                    storage_control.IntelligenceFinding(),
                    storage_control.IntelligenceFinding(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_intelligence_findings(
            request={}, retry=retry, timeout=timeout
        )

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, storage_control.IntelligenceFinding) for i in results)


